      "previewContent": "from typing import List\n\nclass Solution:\n    def fizzBuzz(self, n: int) -> List[str]:\n        rules = [(3, \"Fizz\"), (5, \"Buzz\")]\n        result: List[str] = []\n        for i in range(1, n + 1):\n            word = \"\".join(label for div, label in rules if i % div == 0)\n            result.append(word if word else str(i))\n        return result"
