      "previewContent": "from typing import List\n\nclass Solution:\n    def intersection(self, nums1: List[int], nums2: List[int]) -> List[int]:\n        if len(nums1) > len(nums2):\n            nums1, nums2 = nums2, nums1\n        seen = set(nums1)\n        result = []\n        for x in nums2:\n            if x in seen:\n                result.append(x)\n                seen.remove(x)\n        return result"
